function mostrarPagina(id) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  const el = document.getElementById(id);
  if (el) {
    el.classList.add('active');
    window.scrollTo(0, 0);
  }
}

function login() {
  const usuario = document.getElementById('login-usuario').value.trim().toLowerCase();
  const senha = document.getElementById('login-senha').value;
  const errEl = document.getElementById('login-erro');

  if (!USUARIOS[usuario] || USUARIOS[usuario].senha !== senha) {
    errEl.style.display = 'block';
    errEl.textContent = 'Usuário ou senha inválidos. Tente novamente.';
    document.getElementById('login-senha').value = '';
    return;
  }

  errEl.style.display = 'none';
  usuarioAtual = { ...USUARIOS[usuario], login: usuario };
  iniciarSessao();
}

function iniciarSessao() {
  document.querySelectorAll('.nome-usuario').forEach(el => el.textContent = usuarioAtual.nome);
  document.querySelectorAll('.perfil-usuario').forEach(el => el.textContent = usuarioAtual.label);

  const mapa = {
    tutor: 'page-tutor-home',
    candidato: 'page-candidato-home',
    ong: 'page-ong-home',
    prefeitura: 'page-prefeitura-home'
  };

  mostrarPagina(mapa[usuarioAtual.perfil]);
  renderizarConteudoPerfil();
}

function logout() {
  if (typeof fecharDrawer === "function") fecharDrawer();
  usuarioAtual = null;
  document.getElementById('login-usuario').value = '';
  document.getElementById('login-senha').value = '';
  mostrarPagina('page-login');
}

function renderizarConteudoPerfil() {
  if (usuarioAtual.perfil === 'prefeitura') {
    renderTabelaAdocoes();
    renderTabelaResgates();
    renderTabelaCastracoes();
    renderTabelaDenuncias();
  }
  if (usuarioAtual.perfil === 'ong') {
    renderAnimaisOng();
  }
  if (usuarioAtual.perfil === 'candidato') {
    renderAnimaisAdocao();
  }
  if (usuarioAtual.perfil === 'tutor') {
    renderMeusResgates();
    renderMinhasCastracoes();
  }
}

const fotoAnimais = {1: 'data:image/jpeg;base64,', 2: 'data:image/jpeg;base64,', 3: 'data:image/jpeg;base64,', 4: 'data:image/jpeg;base64,', 5: 'data:image/jpeg;base64,', 6: 'data:image/jpeg;base64,'};
function renderAnimaisAdocao() {
  const el = document.getElementById('animais-adocao-grid');
  if (!el) return;
  const disponiveis = db.animais.filter(a => a.status === 'disponivel');
  el.innerHTML = disponiveis.map(a => `
    <div class="animal-card">
      <div class="animal-photo" style="overflow:hidden;padding:0;height:180px">${fotoAnimais[a.id] ? `<img src="${fotoAnimais[a.id]}" style="width:100%;height:100%;object-fit:cover" alt="">` : `<div style="width:100%;height:100%;background:linear-gradient(135deg,#a8d5b5,#4aad6a);display:flex;align-items:center;justify-content:center;font-size:3rem">🐾</div>`}</div>
      <div class="animal-info">
        <div class="animal-name">${a.nome}</div>
        <div class="animal-details">${a.raca} • ${a.idade} • ${a.sexo}</div>
        <div style="margin-bottom:12px">${a.castrado ? '<span class="badge-status badge-aprovado">Castrado</span>' : '<span class="badge-status badge-pendente">Não castrado</span>'}</div>
        <button class="btn btn-primary btn-sm btn-full" onclick="abrirModalAdocao(${a.id})">Solicitar Adoção</button>
      </div>
    </div>
  `).join('');
}

function abrirModalAdocao(idAnimal) {
  const animal = db.animais.find(a => a.id === idAnimal);
  document.getElementById('modal-adocao-nome').textContent = animal.nome;
  document.getElementById('modal-adocao-id').value = idAnimal;
  abrirModal('modal-adocao');
}

function confirmarAdocao() {
  const idAnimal = parseInt(document.getElementById('modal-adocao-id').value);
  const motivacao = document.getElementById('adocao-motivacao').value;
  if (!motivacao.trim()) { mostrarToast('Preencha a motivação.', 'error'); return; }

  const animal = db.animais.find(a => a.id === idAnimal);
  db.adocoes.push({
    id: db.adocoes.length + 1,
    candidato: usuarioAtual.nome,
    animal: animal.nome,
    status: 'pendente',
    data: new Date().toISOString().slice(0, 10)
  });
  fecharModal('modal-adocao');
  mostrarToast('Solicitação de adoção enviada com sucesso! 🐾', 'success');
  document.getElementById('adocao-motivacao').value = '';
  renderMinhasAdocoes();
}

function renderMinhasAdocoes() {
  const el = document.getElementById('minhas-adocoes-lista');
  if (!el) return;
  const minhas = db.adocoes.filter(a => a.candidato === usuarioAtual.nome);
  if (!minhas.length) {
    el.innerHTML = '<div class="empty-state"><div class="icon">📋</div><h3>Nenhuma solicitação ainda</h3><p>Solicite a adoção de um animal.</p></div>';
    return;
  }
  el.innerHTML = `<div class="table-container"><table><thead><tr><th>Animal</th><th>Data</th><th>Status</th></tr></thead><tbody>` +
    minhas.map(a => `<tr><td data-label="Animal">${a.animal}</td><td data-label="Data">${formatarData(a.data)}</td><td data-label="Status"><span class="badge-status badge-${a.status}">${capitalizar(a.status)}</span></td></tr>`).join('') +
    `</tbody></table></div>`;
}

function renderAnimaisOng() {
  const el = document.getElementById('animais-ong-lista');
  if (!el) return;
  el.innerHTML = `<div class="table-container"><table><thead><tr><th>Nome</th><th>Espécie</th><th>Raça</th><th>Status</th><th>Ações</th></tr></thead><tbody>` +
    db.animais.map(a => `
      <tr>
        <td data-label="Nome">${a.nome}</td>
        <td data-label="Espécie">${a.especie}</td>
        <td data-label="Raça">${a.raca}</td>
        <td data-label="Status"><span class="badge-status badge-${statusClass(a.status)}">${statusLabel(a.status)}</span></td>
        <td data-label="Ações"><div class="table-actions">
          <button class="btn btn-secondary btn-sm" onclick="editarAnimal(${a.id})">Editar</button>
          <button class="btn btn-danger btn-sm" onclick="excluirAnimal(${a.id})">Excluir</button>
        </div></td>
      </tr>`).join('') +
    `</tbody></table></div>`;
}

function editarAnimal(id) {
  const a = db.animais.find(x => x.id === id);
  document.getElementById('edit-animal-id').value = a.id;
  document.getElementById('edit-animal-nome').value = a.nome;
  document.getElementById('edit-animal-especie').value = a.especie;
  document.getElementById('edit-animal-raca').value = a.raca;
  document.getElementById('edit-animal-idade').value = a.idade;
  document.getElementById('edit-animal-status').value = a.status;
  abrirModal('modal-editar-animal');
}

function salvarEdicaoAnimal() {
  const id = parseInt(document.getElementById('edit-animal-id').value);
  const idx = db.animais.findIndex(a => a.id === id);
  db.animais[idx].nome = document.getElementById('edit-animal-nome').value;
  db.animais[idx].especie = document.getElementById('edit-animal-especie').value;
  db.animais[idx].raca = document.getElementById('edit-animal-raca').value;
  db.animais[idx].idade = document.getElementById('edit-animal-idade').value;
  db.animais[idx].status = document.getElementById('edit-animal-status').value;
  fecharModal('modal-editar-animal');
  mostrarToast('Animal atualizado com sucesso!', 'success');
  renderAnimaisOng();
}

function excluirAnimal(id) {
  if (!confirm('Tem certeza que deseja remover este animal?')) return;
  db.animais = db.animais.filter(a => a.id !== id);
  mostrarToast('Animal removido.', 'success');
  renderAnimaisOng();
}

function adicionarAnimal() {
  const nome = document.getElementById('novo-animal-nome').value.trim();
  const especie = document.getElementById('novo-animal-especie').value;
  const raca = document.getElementById('novo-animal-raca').value.trim();
  const idade = document.getElementById('novo-animal-idade').value.trim();
  const sexo = document.getElementById('novo-animal-sexo').value;

  if (!nome || !raca || !idade) { mostrarToast('Preencha todos os campos.', 'error'); return; }

  db.animais.push({
    id: db.animais.length + 1,
    nome, especie, raca, idade, sexo,
    status: 'disponivel', cor: '', peso: '', castrado: false
  });
  fecharModal('modal-novo-animal');
  mostrarToast('Animal cadastrado com sucesso! 🐾', 'success');
  ['novo-animal-nome', 'novo-animal-raca', 'novo-animal-idade'].forEach(id => document.getElementById(id).value = '');
  renderAnimaisOng();
}

