function avancarResgate(id) {
  const r = db.resgates.find(x => x.id === id);
  const fluxo = { pendente: 'em_andamento', em_andamento: 'concluido' };
  if (fluxo[r.status]) { r.status = fluxo[r.status]; mostrarToast('Status atualizado!', 'success'); renderTabelaResgates(); }
}

