function abrirModal(id) {
  document.getElementById(id).classList.add('open');
}
function fecharModal(id) {
  document.getElementById(id).classList.remove('open');
}

function mostrarToast(msg, tipo = 'success') {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = `toast ${tipo}`;
  toast.innerHTML = `${tipo === 'success' ? '✅' : '❌'} ${msg}`;
  container.appendChild(toast);
  setTimeout(() => toast.remove(), 3500);
}

function mudarAba(tabId, btnEl, grupoBtn, grupoConteudo) {
  document.querySelectorAll(`.${grupoConteudo}`).forEach(el => el.classList.add('hidden'));
  document.querySelectorAll(`.${grupoBtn}`).forEach(el => el.classList.remove('active'));
  document.getElementById(tabId).classList.remove('hidden');
  btnEl.classList.add('active');
}

function formatarData(iso) {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

function capitalizar(str) {
  return str.charAt(0).toUpperCase() + str.slice(1).replace(/_/g, ' ');
}

function statusClass(s) {
  return { disponivel: 'aprovado', adotado: 'concluido', em_tratamento: 'em-andamento' }[s] || 'pendente';
}

function statusLabel(s) {
  const labels = {
    pendente: 'Pendente', em_andamento: 'Em andamento', concluido: 'Concluído',
    agendado: 'Agendado', disponivel: 'Disponível', adotado: 'Adotado',
    em_tratamento: 'Em tratamento', aprovado: 'Aprovado', reprovado: 'Reprovado'
  };
  return labels[s] || capitalizar(s);
}

document.addEventListener('keydown', e => {
  if (e.key === 'Enter' && document.getElementById('page-login').classList.contains('active')) login();
});
